// @name Blackjack
// @background #1d4a3a
// @refresh 3600
// Blackjack against the dealer. Pick a bet with the chips, deal, then hit,
// stand, double or split. The dealer draws to 17 (and on a soft 17 when the
// setting says so) and peeks for a blackjack. The bank, the shoe and the round
// on the table are kept in the scene's state, so they outlast a restart.
import {
  MIN_BET, RANKS, activeHand, canDeal, canDouble, canSplit, deal, double, hit, isBlackjack,
  newGame, rankOf, readGame, roundNet, split, stand, suitOf, total,
} from './logic'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it; on color e-paper, left at
// Auto, the table in its solid inks (a muted color there turns to speckle).
const themeOf = (app) => {
  const mode = app.state.contrast || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return 'high'
  return mode === 'auto' && app.frame.paper === true ? 'ink' : 'color'
}

const THEMES = {
  color: {
    page: 'bg-[#1d4a3a] text-[#f4efe3]',
    muted: 'text-[#a8c6b6]',
    panel: 'bg-[#163a2d]',
    face: 'bg-[#fbf8f1] border border-[#cfc6b4]',
    back: 'bg-[#23395b] border-2 border-[#fbf8f1]',
    backInner: 'border-2 border-[#d9a441]',
    red: '#b3261e',
    black: '#1f2430',
    ink: 'text-[#1f2430]',
    inkRed: 'text-[#b3261e]',
    primary: 'bg-[#d9a441] text-[#1d2a22] active:bg-[#c08e30]',
    button: 'bg-[#2d6a53] text-white active:bg-[#245744]',
    off: 'bg-[#24513f] text-[#5f8a77]',
    win: 'bg-[#d9a441] text-[#1d2a22]',
    lose: 'bg-[#163a2d] text-[#a8c6b6]',
    push: 'bg-[#2d6a53] text-white',
    activeRing: 'border-4 border-[#d9a441]',
    idleRing: 'border-4 border-[#1d4a3a]',
    chips: { 5: 'bg-[#c2593a]', 25: 'bg-[#2f6f8f]', 100: 'bg-[#2a2f3d]', 500: 'bg-[#6b3f73]' },
    chipText: 'text-white',
    chipRing: 'border-2 border-white',
    // A chip more than the bank holds: faded on a screen, struck out on e-paper.
    chipOff: 'opacity-40',
    chipOffBg: null,
    chipOffRing: 'border-2 border-white',
    chipOffText: '',
  },
  ink: {
    page: 'bg-[#006b2e] text-white',
    muted: 'text-white',
    panel: 'bg-black',
    face: 'bg-white border-2 border-black',
    back: 'bg-[#0033cc] border-2 border-white',
    backInner: 'border-2 border-[#ffff00]',
    red: '#cc0000',
    black: '#000000',
    ink: 'text-black',
    inkRed: 'text-[#cc0000]',
    primary: 'bg-[#ffff00] text-black',
    button: 'bg-[#006b2e] text-white border-2 border-white',
    off: 'bg-black text-white border border-white line-through',
    win: 'bg-[#ffff00] text-black',
    lose: 'bg-black text-white',
    push: 'bg-white text-black',
    activeRing: 'border-4 border-[#ffff00]',
    idleRing: 'border-4 border-[#006b2e]',
    chips: { 5: 'bg-[#cc0000]', 25: 'bg-[#0033cc]', 100: 'bg-black', 500: 'bg-[#006b2e]' },
    chipText: 'text-white',
    chipRing: 'border-2 border-white',
    chipOff: '',
    chipOffBg: 'bg-black',
    chipOffRing: 'border border-white',
    chipOffText: 'line-through',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    panel: 'bg-white border-2 border-black',
    face: 'bg-white border-2 border-black',
    back: 'bg-black border-2 border-black',
    backInner: 'border-2 border-white',
    red: '#000000',
    black: '#000000',
    ink: 'text-black',
    inkRed: 'text-black',
    primary: 'bg-black text-white',
    button: 'bg-white text-black border-2 border-black',
    off: 'bg-white text-black border border-black line-through',
    win: 'bg-black text-white',
    lose: 'bg-white text-black border-2 border-black',
    push: 'bg-white text-black border-2 border-black',
    activeRing: 'border-4 border-black',
    idleRing: 'border-4 border-white',
    chips: { 5: 'bg-white', 25: 'bg-white', 100: 'bg-white', 500: 'bg-white' },
    chipText: 'text-black',
    chipRing: 'border-4 border-black',
    chipOff: '',
    chipOffBg: 'bg-white',
    chipOffRing: 'border border-black',
    chipOffText: 'line-through',
  },
}

// The four suits as one path each in a 24 x 24 box.
const SUITS = [
  // spades
  'M12 2C9.2 6.6 4 9.2 4 13.8 4 16.2 5.9 18 8.1 18c1.2 0 2.2-.4 2.9-1.1-.2 1.9-1 3.5-2.4 5.1h6.8c-1.4-1.6-2.2-3.2-2.4-5.1.7.7 1.7 1.1 2.9 1.1 2.2 0 4.1-1.8 4.1-4.2C20 9.2 14.8 6.6 12 2z',
  // hearts
  'M12 21.4 10.6 20C5.4 15.4 2 12.3 2 8.5 2 5.4 4.4 3 7.5 3c1.7 0 3.4.8 4.5 2.1C13.1 3.8 14.8 3 16.5 3 19.6 3 22 5.4 22 8.5c0 3.8-3.4 6.9-8.6 11.5z',
  // diamonds
  'M12 2 19.5 12 12 22 4.5 12z',
  // clubs
  'M12 2c2.3 0 4.2 1.9 4.2 4.2 0 1.1-.4 2.1-1.1 2.8.4-.1.7-.1 1.1-.1 2.3 0 4.2 1.9 4.2 4.2s-1.9 4.2-4.2 4.2c-1.2 0-2.3-.5-3-1.3.2 2.2 1 4.1 2.3 6H8.5c1.3-1.9 2.1-3.8 2.3-6-.7.8-1.8 1.3-3 1.3-2.3 0-4.2-1.9-4.2-4.2s1.9-4.2 4.2-4.2c.4 0 .7 0 1.1.1C8.2 8.3 7.8 7.3 7.8 6.2 7.8 3.9 9.7 2 12 2z',
]
const isRed = (suit) => suit === 1 || suit === 2

// In color the red suits are red; in high contrast they are drawn as outlines
// and the black suits solid, so the two colors still read apart.
const Suit = ({ suit, px, t, hc }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px}px] h-[${px}px]`}>
    {hc && isRed(suit) ? (
      <path d={SUITS[suit]} fill="#ffffff" stroke="#000000" strokeWidth={2.2} strokeLinejoin="round" />
    ) : (
      <path d={SUITS[suit]} fill={isRed(suit) ? t.red : t.black} />
    )}
  </svg>
)

const Card = ({ card, w, h, t, hc, hidden }) => {
  const radius = Math.max(4, Math.round(h * 0.06))
  if (hidden) {
    const inset = Math.max(4, Math.round(w * 0.08))
    return (
      <div className={`w-[${w}px] h-[${h}px] rounded-[${radius}px] flex ${t.back}`}>
        <div className={`flex-1 m-[${inset}px] rounded-[${Math.max(2, radius - 3)}px] ${t.backInner}`} />
      </div>
    )
  }
  const suit = suitOf(card)
  const rank = RANKS[rankOf(card)]
  const pad = Math.max(3, Math.round(w * 0.07))
  const rankPx = Math.round(h * (rank === '10' ? 0.19 : 0.22))
  return (
    <div className={`w-[${w}px] h-[${h}px] rounded-[${radius}px] p-[${pad}px] flex flex-col ${t.face}`}>
      <span className={`text-[${rankPx}px] font-bold leading-none ${isRed(suit) ? t.inkRed : t.ink}`}>{rank}</span>
      <div className="mt-1">
        <Suit suit={suit} px={Math.round(h * 0.14)} t={t} hc={hc} />
      </div>
      <div className="flex-1 flex items-center justify-center">
        <Suit suit={suit} px={Math.round(Math.min(w * 0.55, h * 0.36))} t={t} hc={hc} />
      </div>
    </div>
  )
}

/** A hand's cards fanned to the right, as wide as `width` allows. */
const Fan = ({ cards, w, h, width, t, hc, hideSecond }) => {
  const n = cards.length
  const step = n > 1 ? Math.min(w * 0.58, (width - w) / (n - 1)) : 0
  const used = Math.round(w + step * (n - 1))
  return (
    <div className={`relative w-[${used}px] h-[${h}px]`}>
      {cards.map((card, i) => (
        <div className={`absolute top-0 left-[${Math.round(i * step)}px]`}>
          <Card card={card} w={w} h={h} t={t} hc={hc} hidden={hideSecond && i === 1} />
        </div>
      ))}
    </div>
  )
}

// A chip of `value`, `px` across; one the bank cannot cover yet is faded or struck out.
const Chip = ({ value, px, least, ok, t, onClick }) => (
  <div className={`w-[${px}px] h-[${px}px] rounded-full flex p-[${Math.round(px * 0.09)}px] ${ok ? t.chips[value] : `${t.chipOffBg || t.chips[value]} ${t.chipOff}`}`}
    onClick={onClick}>
    <div className={`flex-1 rounded-full flex items-center justify-center text-[${Math.max(least || 0, Math.round(px * (value >= 100 ? 0.3 : 0.36)))}px] font-bold ${t.chipText} ${ok ? t.chipRing : `${t.chipOffRing} ${t.chipOffText}`}`}>
      {value}
    </div>
  </div>
)

const money = (n) => {
  const abs = Math.abs(n)
  const text = Number.isInteger(abs) ? String(abs) : abs.toFixed(2)
  return `${n < 0 ? '−' : ''}$${text}`
}

// A label's type: at most `px`, and small enough for it to fit `w` on one
// line (Ubuntu bold is about half an em a character), never under `least`.
const fitPx = (text: string, w: number, px: number, least = 12) =>
  Math.round(Math.max(least, Math.min(px, w / (String(text).length * 0.56))))
// "Deal $25" where the amount fits its button at 13 px or more, else "Deal".
const dealLabel = (bet: number, w: number, px: number) =>
  !bet ? 'Deal' : w / (`Deal ${money(bet)}`.length * 0.56) >= Math.min(px, 13) ? `Deal ${money(bet)}` : 'Deal'

const RESULT_WORDS = { blackjack: 'Blackjack!', win: 'Win', lose: 'Lose', push: 'Push', bust: 'Bust' }

const rulesOf = (app) => {
  const decks = parseInt(app.state.decks, 10)
  return {
    decks: [1, 2, 4, 6, 8].includes(decks) ? decks : 6,
    hitSoft17: (app.state.soft17 || 'hit') === 'hit',
    payout: app.state.payout === '1.2' ? 1.2 : 1.5,
  }
}
const startingBank = (app) => {
  const n = parseInt(app.state.bankroll, 10)
  return n > 0 ? n : 500
}

// The table and the panel read the game through signals: a tap runs only
// the one whose part changed (a chip: the panel alone), not get(). The game
// shown and its app are kept for the handlers, which change them.
const tableGame = signal(null)
const panelGame = signal(null)
const confirming = signal(false)
let game = null
let gameApp = null

// What the table draws of a game: its cards, bets and results, and whose turn.
const tableOf = (g) => JSON.stringify([g.dealer, g.hands, g.phase, g.active])
const show = (g, confirm: boolean) => {
  const table = tableGame.peek()
  if (!table || tableOf(table) !== tableOf(g)) tableGame.value = g
  if (JSON.stringify(panelGame.peek()) !== JSON.stringify(g)) panelGame.value = g
  confirming.value = confirm
}
const setConfirm = (on: boolean) => {
  frameos.remember('confirm', on)
  confirming.value = on
}

const loadGame = (app) => {
  const kept = readGame(app.state.game)
  if (kept) return kept
  const game = newGame(startingBank(app), Date.now() % 2147483647, rulesOf(app))
  frameos.setState('game', game)
  return game
}

// Every action works on a copy of the game and saves (and shows) it when it did something.
const act = (app, fn) => {
  const copy = JSON.parse(JSON.stringify(game))
  if (fn(copy, rulesOf(app)) === false) return false
  frameos.setState('game', copy)
  game = copy
  show(copy, !!frameos.recall('confirm'))
  return true
}

const resetBank = (app) => {
  const fresh = newGame(startingBank(app), (Date.now() ^ game.seed) % 2147483647, rulesOf(app))
  frameos.setState('game', fresh)
  game = fresh
  setConfirm(false)
  show(fresh, false)
}

const addChip = (app, value) =>
  act(app, (g) => {
    if (g.phase === 'play' || g.bet + value > g.bank) return false
    g.bet += value
  })

export function onEvent(app, context) {
  game = loadGame(app)
  gameApp = app
  const p = context.payload || {}
  const playing = game.phase === 'play'
  if (context.event === 'forward') return playing ? act(app, hit) : act(app, deal)
  if (context.event === 'back') return playing ? act(app, stand) : false
  if (context.event !== 'keyDown' || p.ctrl || p.alt || p.meta) return false
  const key = String(p.key || '').toLowerCase()
  if (playing) {
    if (key === 'h') return act(app, hit)
    if (key === 's') return act(app, stand)
    if (key === 'd') return act(app, double)
    if (key === 'p') return act(app, split)
    return false
  }
  if (key === 'enter' || key === ' ') return act(app, deal)
  if (key === '1') return addChip(app, 5)
  if (key === '2') return addChip(app, 25)
  if (key === '3') return addChip(app, 100)
  if (key === '4') return addChip(app, 500)
  if (key === 'backspace') return act(app, (g) => { g.bet = 0 })
  return false
}

// The dealer's row over the player's hands.
const Table = memo(({ tableW, tableH, gap, zoneH, labelPx, labelH, t, hc, payout, hitSoft17 }) => {
  const game = tableGame.value
  const playing = game.phase === 'play'
  const dealt = game.hands.length > 0

  // One card size for the whole table: the tallest that fits a zone, and
  // narrow enough that each hand shows two and a half cards side by side.
  const handCount = Math.max(1, game.hands.length)
  const colW = Math.floor((tableW - (handCount - 1) * gap) / handCount)
  const cardH = Math.floor(Math.min(zoneH - labelH - 10, ((colW - 8) / (1 + 0.58 * 1.6)) / 0.7))
  const cardW = Math.round(cardH * 0.7)

  // The dealer's row: the hole card stays down while the player plays.
  const dealerTotal = total(game.dealer).value
  const upTotal = game.dealer.length ? total([game.dealer[0]]).value : 0
  const dealerLabel = !dealt ? 'Dealer' : playing ? `Dealer shows ${upTotal}` : isBlackjack(game.dealer) ? 'Dealer has blackjack' : dealerTotal > 21 ? `Dealer busts with ${dealerTotal}` : `Dealer has ${dealerTotal}`

  const badge = (hand) => {
    if (!hand.result) return null
    const cls = hand.result === 'win' || hand.result === 'blackjack' ? t.win : hand.result === 'push' ? t.push : t.lose
    const net = hand.paid - hand.bet
    return (
      <span className={`shrink-0 whitespace-nowrap rounded-lg px-2 text-[${labelPx}px] font-bold leading-[1.4] ${cls}`}>
        {`${RESULT_WORDS[hand.result]} ${net > 0 ? '+' : ''}${net ? money(net) : ''}`}
      </span>
    )
  }

  const handLabel = (hand) => {
    const tot = total(hand.cards)
    const words = isBlackjack(hand.cards) && !hand.split && game.hands.length === 1 ? 'Blackjack' : `${tot.soft && tot.value < 21 ? 'Soft ' : ''}${tot.value}`
    // Once paid, the badge says the money; before, the label says the stake.
    if (hand.result === 'blackjack') return ''
    return hand.result ? words : `${words} · ${money(hand.bet)}${hand.doubled ? ' doubled' : ''}`
  }

  return (
    <div className={`flex flex-col w-[${tableW}px] h-[${tableH}px] gap-[${gap}px]`}>
      <div className={`flex flex-col items-center h-[${zoneH}px] w-full`}>
        <div className={`h-[${labelH}px] flex items-center whitespace-nowrap text-[${fitPx(dealerLabel, tableW - 4, labelPx, 11)}px] font-bold ${t.muted}`}>{dealerLabel}</div>
        {dealt ? (
          <Fan cards={game.dealer} w={cardW} h={cardH} width={tableW} t={t} hc={hc} hideSecond={playing} />
        ) : (
          // The rules in two pieces that wrap between them, never inside one.
          <div className="flex-1 flex flex-col justify-center w-full">
            <div className={`w-full flex flex-wrap justify-center gap-x-[${Math.round(labelPx * 0.3)}px] text-[${labelPx}px] ${t.muted}`}>
              <span className="whitespace-nowrap">{`Blackjack pays ${payout === 1.5 ? '3 to 2' : '6 to 5'} ·`}</span>
              <span className="whitespace-nowrap">{`dealer ${hitSoft17 ? 'hits' : 'stands on'} soft 17`}</span>
            </div>
          </div>
        )}
      </div>
      <div className={`flex justify-center h-[${zoneH}px] w-full gap-[${gap}px]`}>
        {dealt ? (
          game.hands.map((hand, i) => {
            const lit = playing && i === game.active && game.hands.length > 1
            return (
              <div className={`flex flex-col items-center w-[${colW}px] rounded-xl ${game.hands.length > 1 ? (lit ? t.activeRing : t.idleRing) : ''}`}>
                <div className={`h-[${labelH}px] flex items-center gap-2 text-[${labelPx}px] font-bold`}>
                  <span className="truncate">{handLabel(hand)}</span>
                  {badge(hand)}
                </div>
                <Fan cards={hand.cards} w={cardW} h={cardH} width={colW - 8} t={t} hc={hc} hideSecond={false} />
              </div>
            )
          })
        ) : (
          <div className="flex flex-col items-center justify-center gap-2">
            <span className={`text-[${fitPx('Blackjack', tableW - 4, labelPx * 1.8, labelPx)}px] font-black`}>Blackjack</span>
            <span className={`text-center text-[${labelPx}px] ${t.muted}`}>Pick a bet with the chips, then deal.</span>
          </div>
        )}
      </div>
    </div>
  )
})

// The bank, the news and the buttons: beside the table on a wide screen, under it otherwise.
const Panel = memo(({ wide, narrow, twoRows, panelW, panelH, gap, rowH, chipH, headH, font, t, start }) => {
  const game = panelGame.value
  const confirm = confirming.value
  const app = gameApp
  const playing = game.phase === 'play'
  const dealt = game.hands.length > 0
  const broke = !playing && game.bank < MIN_BET

  // The round's outcome, the shoe's news, or whose turn it is.
  let message = ''
  if (broke) message = 'Out of chips'
  else if (playing) message = game.hands.length > 1 ? `Hand ${game.active + 1} of ${game.hands.length}` : 'Hit or stand?'
  else if (dealt) {
    const net = roundNet(game)
    message = net > 0 ? `You win ${money(net)}` : net < 0 ? `You lose ${money(-net)}` : 'Push: your bet back'
  } else message = 'Place your bet'
  if (game.shuffled && playing) message = 'New shoe. ' + message

  const button = (label, cls, onClick, w, h) => (
    <div className={`w-[${w}px] h-[${h}px] rounded-xl flex items-center justify-center whitespace-nowrap text-[${fitPx(label, w - 12, font)}px] font-bold ${cls}`} onClick={onClick}>
      {label}
    </div>
  )
  const maybe = (ok, label, onClick, w, h) => button(label, ok ? t.button : t.off, ok ? onClick : () => false, w, h)

  const chip = (value, px) => <Chip value={value} px={px} ok={!playing && game.bet + value <= game.bank} t={t} onClick={() => addChip(app, value)} />

  // What the panel's buttons are: confirm a reset, start over when broke,
  // play the hand, or pick the next bet.
  // In a wide panel the buttons go in two rows; stacked under the table, in one.
  const controls = (w, h, oneRow) => {
    const half = Math.floor((w - gap) / 2)
    const quarter = Math.floor((w - 3 * gap) / 4)
    const rows = (a, b) => (oneRow ? [<div className={`flex gap-[${gap}px]`}>{a}{b}</div>] : [<div className={`flex gap-[${gap}px]`}>{a}</div>, <div className={`flex gap-[${gap}px]`}>{b}</div>])
    if (confirm) {
      const ask = <span className={`text-[${Math.round(font * 0.8)}px] ${oneRow ? 'flex-1 self-center' : 'text-center'}`}>{`Start again with ${money(start)}?`}</span>
      const pair = [
        button('Cancel', t.button, () => setConfirm(false), oneRow ? quarter : half, h),
        button('Reset', t.primary, () => resetBank(app), oneRow ? quarter : half, h),
      ]
      return oneRow ? [<div className={`flex gap-[${gap}px]`}>{ask}{pair}</div>] : [ask, <div className={`flex gap-[${gap}px]`}>{pair}</div>]
    }
    if (broke) return [button(`Start again with ${money(start)}`, t.primary, () => resetBank(app), w, h)]
    if (playing) {
      const bw = oneRow ? quarter : half
      return rows(
        [button('Hit', t.primary, () => act(app, hit), bw, h), button('Stand', t.primary, () => act(app, stand), bw, h)],
        [maybe(canDouble(game), 'Double', () => act(app, double), bw, h), maybe(canSplit(game), 'Split', () => act(app, split), bw, h)],
      )
    }
    if (oneRow) {
      // Four chips as tall as the row, then Clear and Deal share what is left.
      const chipPx = Math.floor(Math.min(h, (w - 5 * gap) * 0.12))
      const rest = w - 4 * chipPx - 5 * gap
      const clearW = Math.floor(rest * 0.4)
      return [
        <div className={`flex items-center gap-[${gap}px]`}>
          {chip(5, chipPx)}
          {chip(25, chipPx)}
          {chip(100, chipPx)}
          {chip(500, chipPx)}
          {maybe(game.bet > 0, 'Clear', () => act(app, (g) => { g.bet = 0 }), clearW, h)}
          {button(dealLabel(game.bet, rest - clearW - 12, font), canDeal(game) ? t.primary : t.off, () => act(app, deal), rest - clearW, h)}
        </div>,
      ]
    }
    const chipPx = Math.floor(Math.min((w - 3 * gap) / 4, chipH))
    return [
      <div className={`flex justify-between w-[${w}px]`}>
        {chip(5, chipPx)}
        {chip(25, chipPx)}
        {chip(100, chipPx)}
        {chip(500, chipPx)}
      </div>,
      <div className={`flex gap-[${gap}px]`}>
        {maybe(game.bet > 0, 'Clear', () => act(app, (g) => { g.bet = 0 }), half, h)}
        {button(dealLabel(game.bet, half - 12, font), canDeal(game) ? t.primary : t.off, () => act(app, deal), half, h)}
      </div>,
    ]
  }

  const resetLink = !playing && !confirm && !broke ? (
    <div className={`h-[${headH}px] ${narrow ? 'px-2' : 'px-3'} shrink-0 whitespace-nowrap rounded-lg flex items-center text-[${Math.round(font * 0.7)}px] underline ${t.muted}`}
      onClick={() => setConfirm(true)}>
      {narrow ? 'Reset' : 'Reset bank'}
    </div>
  ) : null

  if (wide) {
    const inner = panelW - 2 * gap
    return (
      <div className={`flex flex-col justify-between w-[${panelW}px] h-[${panelH}px] rounded-2xl p-[${gap}px] ${t.panel}`}>
        <div className="flex flex-col">
          {panelH >= 240 ? <span className={`text-[${Math.round(font * 0.6)}px] uppercase font-bold ${t.muted}`}>Bank</span> : null}
          <span className={`text-[${Math.round(font * 1.6)}px] font-black leading-none`}>{money(game.bank)}</span>
          <span className={`${panelH >= 240 ? 'mt-2' : 'mt-1'} text-[${Math.round(font * 0.75)}px] ${t.muted}`}>
            {playing ? `On the table ${money(game.hands.reduce((s, h) => s + h.bet, 0))}` : `Next bet ${money(game.bet)}`}
          </span>
        </div>
        <span className={`text-[${Math.round(font * 0.95)}px] font-bold leading-tight`}>{message}</span>
        <div className={`flex flex-col gap-[${gap}px]`}>{controls(inner, rowH, false)}</div>
        <div className="flex items-center justify-between">
          <div className={`flex-1 min-w-0 flex flex-wrap gap-x-[${Math.round(font * 0.2)}px] leading-tight text-[${Math.round(font * 0.6)}px] ${t.muted}`}>
            <span className="whitespace-nowrap">{`Best ${money(game.stats.best)} ·`}</span>
            <span className="whitespace-nowrap">{`${game.stats.rounds} ${game.stats.rounds === 1 ? 'round' : 'rounds'}`}</span>
          </div>
          {resetLink}
        </div>
      </div>
    )
  }

  // Stacked: the bank and buttons under the table; on a narrow screen (a
  // watch) or a tall one the buttons in two rows, as beside the table.
  const ctrl = controls(panelW - 2 * gap, rowH, !twoRows)
  return (
    <div className={`flex flex-col w-[${panelW}px] h-[${panelH}px] rounded-2xl p-[${gap}px] gap-[${gap}px] ${t.panel}`}>
      <div className={`flex items-center h-[${headH}px] ${narrow ? 'gap-2' : 'gap-3'}`}>
        <span className={`text-[${Math.round(font * 1.1)}px] font-black`}>{money(game.bank)}</span>
        <span className={`flex-1 truncate text-[${Math.round(font * 0.8)}px] font-bold`}>{message}</span>
        {resetLink}
      </div>
      {ctrl}
    </div>
  )
})

// A round panel (only the circle inside the square shows): the table in the
// square inside the circle, the bank and the news in the arc above it, the
// chips (or Double and Split) along the square's foot, and the two main
// buttons in the arc below, as wide as the circle is there.
const roundRoom = (W: number, H: number) => {
  const r = Math.min(W, H) / 2
  const side = Math.floor((r - 12) * Math.SQRT2)
  // How wide a row may be whose far edge is dy px from the centre.
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, (r - 12) * (r - 12) - dy * dy)))
  return { side, x0: (W - side) >> 1, y0: (H - side) >> 1, chord }
}

const roundMessage = (game) => {
  const playing = game.phase === 'play'
  let message = ''
  if (!playing && game.bank < MIN_BET) message = 'Out of chips'
  else if (playing) message = game.hands.length > 1 ? `Hand ${game.active + 1} of ${game.hands.length}` : 'Hit or stand?'
  else if (game.hands.length > 0) {
    const net = roundNet(game)
    message = net > 0 ? `You win ${money(net)}` : net < 0 ? `You lose ${money(-net)}` : 'Push: your bet back'
  } else message = game.bet ? `Bet ${money(game.bet)}` : 'Place your bet'
  if (game.shuffled && playing) message = 'New shoe. ' + message
  return message
}

// The arc above the table: the bank and the news, on one line as wide as the circle there.
const RoundTop = memo(({ w, h, font, t }) => {
  const game = panelGame.value
  return (
    <div className={`flex items-end justify-center w-[${w}px] h-[${h}px]`}>
      <div className={`flex items-baseline gap-[${Math.round(font * 0.5)}px] max-w-[${w}px]`}>
        <span className={`shrink-0 text-[${Math.round(font * 1.3)}px] font-black leading-none`}>{money(game.bank)}</span>
        <span className={`truncate text-[${font}px] font-bold ${t.muted}`}>{roundMessage(game)}</span>
      </div>
    </div>
  )
})

// The square's foot: the chips while betting, Double and Split while playing.
const RoundMid = memo(({ w, h, gap, font, t, start }) => {
  const game = panelGame.value
  const confirm = confirming.value
  const app = gameApp
  const playing = game.phase === 'play'
  if (confirm || (!playing && game.bank < MIN_BET)) {
    return (
      <div className={`flex items-center justify-center w-[${w}px] h-[${h}px] text-[${font}px] font-bold`}>
        {confirm ? `Start again with ${money(start)}?` : 'Out of chips'}
      </div>
    )
  }
  if (playing) {
    const half = Math.floor((w - gap) / 2)
    const maybe = (ok, label, onClick) => (
      <div className={`w-[${half}px] h-[${h}px] rounded-xl flex items-center justify-center text-[${font}px] font-bold ${ok ? t.button : t.off}`}
        onClick={ok ? onClick : () => false}>
        {label}
      </div>
    )
    return (
      <div className={`flex gap-[${gap}px] w-[${w}px] h-[${h}px]`}>
        {maybe(canDouble(game), 'Double', () => act(app, double))}
        {maybe(canSplit(game), 'Split', () => act(app, split))}
      </div>
    )
  }
  // Four chips, then Reset bank.
  const px = Math.floor(Math.min(h, (w - 4 * gap) / 5.3))
  const chip = (value) => <Chip value={value} px={px} least={14} ok={game.bet + value <= game.bank} t={t} onClick={() => addChip(app, value)} />
  return (
    <div className={`flex items-center justify-center gap-[${gap}px] w-[${w}px] h-[${h}px]`}>
      {chip(5)}
      {chip(25)}
      {chip(100)}
      {chip(500)}
      <div className={`h-[${px}px] px-2 rounded-lg flex items-center text-[${Math.max(14, Math.round(font * 0.75))}px] underline ${t.muted}`}
        onClick={() => setConfirm(true)}>
        Reset
      </div>
    </div>
  )
})

// The arc below the table: Clear and Deal, Hit and Stand, or Cancel and Reset.
const RoundBottom = memo(({ w, h, gap, font, t, start }) => {
  const game = panelGame.value
  const confirm = confirming.value
  const app = gameApp
  const playing = game.phase === 'play'
  const half = Math.floor((w - gap) / 2)
  const button = (label, cls, onClick, bw = half) => (
    <div className={`w-[${bw}px] h-[${h}px] rounded-xl flex items-center justify-center whitespace-nowrap text-[${fitPx(label, bw - 8, font)}px] font-bold ${cls}`} onClick={onClick}>
      {label}
    </div>
  )
  let buttons
  if (confirm) buttons = [button('Cancel', t.button, () => setConfirm(false)), button('Reset', t.primary, () => resetBank(app))]
  else if (!playing && game.bank < MIN_BET) buttons = [button(`Start again`, t.primary, () => resetBank(app), w)]
  else if (playing) buttons = [button('Hit', t.primary, () => act(app, hit)), button('Stand', t.primary, () => act(app, stand))]
  else {
    buttons = [
      button('Clear', game.bet > 0 ? t.button : t.off, game.bet > 0 ? () => act(app, (g) => { g.bet = 0 }) : () => false),
      button(dealLabel(game.bet, half - 8, font), canDeal(game) ? t.primary : t.off, () => act(app, deal)),
    ]
  }
  return <div className={`flex justify-center gap-[${gap}px] w-[${w}px]`}>{buttons}</div>
})

export function get(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const round = context.round === true
  const look = themeOf(app)
  const hc = look === 'high'
  const t = THEMES[look]
  game = loadGame(app)
  gameApp = app
  const rules = rulesOf(app)
  show(game, !!frameos.recall('confirm'))

  const m = Math.round(Math.min(W, H) * 0.035)
  const gap = Math.round(m * 0.6)
  const wide = W >= H * 1.2
  // Beside the table the panel takes 210 px, or about half a small screen.
  const panelW = wide ? Math.round(Math.max(Math.min(210, W * 0.525), Math.min(W * 0.3, 420))) : W - 2 * m
  // Under the table, the chips, Clear and Deal in one row where they fit
  // (about 340 px), else in two rows, a little lower. A tall screen has the
  // room for two rows and larger chips too.
  const narrow = !wide && W - 2 * m - 2 * gap < 340
  const tall = !wide && H >= W * 1.3
  const twoRows = narrow || tall
  const rowH = narrow
    ? Math.round(Math.max(34, Math.min(H * 0.12, 48)))
    : Math.round(Math.max(Math.min(48, H * 0.18), Math.min(Math.min(W, H) * 0.12, 96)))
  const font = Math.round(Math.max(16, Math.min(rowH * 0.36, 34)))
  // The line with the bank and the news (as tall as the Reset link in it),
  // and the chips' row when they have one of their own.
  const headH = narrow ? Math.round(Math.max(26, font * 1.5)) : Math.min(44, rowH)
  const chipH = wide ? rowH * 1.15 : Math.floor(Math.min((W - 2 * m - 5 * gap) / 4, rowH * (narrow ? 1 : 1.5)))
  const panelH = wide ? H - 2 * m
    : twoRows ? 2 * gap + headH + gap + Math.max(chipH, rowH) + gap + rowH
    : 2 * gap + headH + gap + rowH
  const tableW = wide ? W - panelW - 3 * m : W - 2 * m
  const tableH = wide ? H - 2 * m : H - panelH - 3 * m
  const zoneH = Math.floor((tableH - gap) / 2)
  // Smaller words on a narrow table or a short one, so the cards keep their room.
  const labelPx = Math.round(Math.max(tableW < 200 || zoneH < 90 ? 13 : 16, Math.min(zoneH * 0.11, 30)))
  const labelH = Math.round(labelPx * 1.6)

  if (round) {
    const { side, x0, y0, chord } = roundRoom(W, H)
    const g = Math.max(6, Math.round(side * 0.025))
    const midH = Math.round(side * 0.17)
    const rTableH = side - midH - g
    const rZoneH = Math.floor((rTableH - g) / 2)
    const rLabelPx = Math.round(Math.max(14, Math.min(rZoneH * 0.13, 30)))
    const rFont = Math.round(Math.max(14, Math.min(side * 0.055, 30)))
    const topFont = Math.round(Math.max(14, Math.min(y0 * 0.23, 28)))
    const bh = Math.max(36, Math.round(y0 * 0.52))
    const bTop = y0 + side + Math.max(6, Math.round(y0 * 0.1))
    const bw = chord(bTop + bh - H / 2)
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        <div className={`absolute left-[${x0}px] top-0`}>
          <RoundTop w={side} h={y0 - Math.max(6, Math.round(y0 * 0.12))} font={topFont} t={t} />
        </div>
        <div className={`absolute left-[${x0}px] top-[${y0}px] flex flex-col gap-[${g}px]`}>
          <Table tableW={side} tableH={rTableH} gap={g} zoneH={rZoneH} labelPx={rLabelPx} labelH={Math.round(rLabelPx * 1.5)} t={t} hc={hc}
            payout={rules.payout} hitSoft17={rules.hitSoft17} />
          <RoundMid w={side} h={midH} gap={g} font={rFont} t={t} start={startingBank(app)} />
        </div>
        <div className={`absolute left-0 top-[${bTop}px] w-[${W}px] flex justify-center`}>
          <RoundBottom w={bw} h={bh} gap={10} font={Math.max(14, Math.min(rFont, Math.round(bh * 0.42)))} t={t} start={startingBank(app)} />
        </div>
      </div>
    )
  }

  const table = (
    <Table tableW={tableW} tableH={tableH} gap={gap} zoneH={zoneH} labelPx={labelPx} labelH={labelH} t={t} hc={hc}
      payout={rules.payout} hitSoft17={rules.hitSoft17} />
  )
  const panel = <Panel wide={wide} narrow={narrow} twoRows={twoRows} panelW={panelW} panelH={panelH} gap={gap} rowH={rowH} chipH={chipH} headH={headH} font={font} t={t} start={startingBank(app)} />

  if (wide) {
    return (
      <div className={`flex w-full h-full p-[${m}px] gap-[${m}px] ${t.page}`}>
        {table}
        {panel}
      </div>
    )
  }

  // Stacked: the table on top, the bank and buttons under it.
  return (
    <div className={`flex flex-col items-center w-full h-full p-[${m}px] gap-[${m}px] ${t.page}`}>
      {table}
      {panel}
    </div>
  )
}

